def run(durs,start=30,ls=30,ld=100,cap=.85,save=False):
 s.reset();sc5=0;sc10=0;acts=[]
 times=np.r_[start,start+np.cumsum(durs)];levels=np.array([0,.25,.5,.7,cap])
 for t in range(500):
  w,x,y,z=d.qpos[3:7];pitch=np.arcsin(np.clip(2*(w*y-z*x),-1,1));c=p[0]*d.qpos[0]+p[1]*d.qvel[0]+p[2]*pitch+p[3]*d.qvel[4]
  target=base.copy();target[[4,9]]=np.clip(-.4+c,-.87,.52);target[[2,7]]=-.4+p[4]*c+p[5]
  f=np.clip((t-ls)/ld,0,1);target[li]=base[li]*(1-f)+left*f
  f=np.interp(t,times,levels)*20;j=min(int(f),19);f=f-j;target[ri]=path[j]*(1-f)+path[j+1]*f
  target[43:48]=grip[:5]
  for k in (48,51,54,58):target[k:k+3]=grip[5:8]
  target[57]=grip[8]
  a=np.clip(2*(target-lo)/(hi-lo)-1,-1,1)
  if save:acts.append(a.copy())
  _,_,done=s.step(a)
  dot=np.array([np.dot(d.xquat[71],goal),np.dot(d.xquat[72],goal)])
  sc5+=np.sum(np.exp(-5*(1-dot)))/2;sc10+=np.sum(np.exp(-10*(1-dot)))/2
  if done:break
 return t+1,sc5/500,sc10/500,dot,np.array(acts)

