  n,s5,s10,dot,_=run(durs)
  score=(s5+s10)/2
  if score>best:
   best=score;bestdurs=durs.copy();np.savez('/tmp/best_schedule.npz',durs=durs,n=n,s5=s5,s10=s10,score=score)
   print('BEST',i,'score',round(score,4),'n',n,'s5',round(s5,3),'s10',round(s10,3),'durs',durs.round(1),'dot',dot.round(3),flush=True)
